package com.komainos.ejecucion;
import com.komainos.ejecucion.service.*;import com.komainos.ejecucion.model.*;import com.komainos.ejecucion.config.PropiedadesAutomatizacion;import com.komainos.inventario.model.FamiliaSistemaOperativo;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.*;import java.util.Map;import static org.assertj.core.api.Assertions.*;
class AdaptadoresTest {
 private final ObjectMapper json=new ObjectMapper();
 private SolicitudEjecucion solicitud(boolean analisis,boolean posterior){return new SolicitudEjecucion(1,"srv-prueba","192.0.2.1",FamiliaSistemaOperativo.LINUX,99,"NO DEBE EJECUTARSE",Map.of(),analisis,posterior,1);}
 @Test @DisplayName("RF37/RF52: el modo local devuelve métricas estáticas sin abrir un transporte") void simulado(){var a=new AnsibleSimulado(json,new PropiedadesAutomatizacion("SIMULADO",false,"ejecutable-inexistente",Map.of()));var antes=a.ejecutar(solicitud(true,false));var despues=a.ejecutar(solicitud(true,true));assertThat(antes.simulado()).isTrue();assertThat(antes.metricas()).hasSize(8);assertThat(despues.metricas().get(1).valor()).isLessThan(antes.metricas().get(1).valor());assertThat(a.ejecutar(solicitud(false,false)).correcto()).isTrue();}
 @Test @DisplayName("RF59: se puede reproducir un fallo de tarea de forma estática")void fallo(){var a=new AnsibleSimulado(json,new PropiedadesAutomatizacion("SIMULADO",false,"no-existe",Map.of("srv-prueba","FALLO_TAREA")));assertThat(a.ejecutar(solicitud(false,false)).correcto()).isFalse();assertThat(a.ejecutar(solicitud(true,false)).correcto()).isTrue();}
 @Test @DisplayName("Contrato: rechaza métricas repetidas, vacías o con tipos mezclados")void contrato(){for(String s:new String[]{"{}","{\"metricas\":[]}","{\"metricas\":[{\"codigo\":\"cpu\",\"valor\":\"malo\"}]}","{\"metricas\":[{\"codigo\":\"cpu\",\"valor\":1},{\"codigo\":\"cpu\",\"valor\":2}]}"})assertThatThrownBy(()->ContratoAnalisis.leer(s,json)).isInstanceOf(com.komainos.shared.exception.ReglaNegocioException.class);}
 @Test @DisplayName("RNF11: limpia contraseñas, tokens y llaves antes de persistir la salida")void secretos(){String s=SanitizadorSalida.limpiar("password=abc\ntoken: xyz\n-----BEGIN PRIVATE KEY-----\nprivada\n-----END PRIVATE KEY-----\nclave: valor-secreto","valor-secreto");assertThat(s).doesNotContain("abc","xyz","privada","valor-secreto");}
 @Test @DisplayName("RF26: los argumentos del transporte se citan como literales")void argumentos(){assertThat(AnsibleReal.citar("a'b; $(id)",false)).isEqualTo("'a'\"'\"'b; $(id)'");assertThat(AnsibleReal.citar("a'b",true)).isEqualTo("'a''b'");}
}
